'use strict';
// ============================================================================
// E-TRADE — Automatizare identificare produse (server, fisier unic)
// Fara nicio dependenta externa — doar module native Node.js.
// ============================================================================
const http = require('http');
const https = require('https');
const net = require('net');
const tls = require('tls');
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const { URL } = require('url');
const { DatabaseSync } = require('node:sqlite');

// ---------- .env loader minimal ----------
(function loadEnv(file = path.join(__dirname, '.env')) {
  if (!fs.existsSync(file)) return;
  const content = fs.readFileSync(file, 'utf8');
  content.split(/\r?\n/).forEach((line) => {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) return;
    const idx = trimmed.indexOf('=');
    if (idx === -1) return;
    const key = trimmed.slice(0, idx).trim();
    let value = trimmed.slice(idx + 1).trim();
    if ((value.startsWith('"') && value.endsWith('"')) || (value.startsWith("'") && value.endsWith("'"))) {
      value = value.slice(1, -1);
    }
    if (!(key in process.env)) process.env[key] = value;
  });
})();

const PORT = parseInt(process.env.PORT || '3000', 10);
// DATA_ROOT permite mutarea bazei de date + pozelor pe un disc persistent
// (ex. un disc Render montat la /var/data) - vezi README pentru instructiuni.
// Fara DATA_ROOT setat, foloseste un folder local (comportament neschimbat).
const DATA_ROOT = process.env.DATA_ROOT || __dirname;
const DATA_DIR = path.join(DATA_ROOT, 'data');
const UPLOAD_DIR = path.join(DATA_ROOT, 'uploads');
if (!fs.existsSync(DATA_DIR)) fs.mkdirSync(DATA_DIR, { recursive: true });
if (!fs.existsSync(UPLOAD_DIR)) fs.mkdirSync(UPLOAD_DIR, { recursive: true });

const NOTIFY_EMAIL = process.env.NOTIFY_EMAIL || 'office@echychiatrade.ro';
const WHATSAPP_NUMBER = process.env.WHATSAPP_NUMBER || '40724306364';

// ---------- HTML-urile publice (incarcate din text codat base64, mai jos in fisier) ----------
const INDEX_HTML = Buffer.from('', 'base64').toString('utf8');
const ADMIN_HTML = Buffer.from('', 'base64').toString('utf8');
const ICON_192 = Buffer.from('', 'base64');
const ICON_512 = Buffer.from('', 'base64');
const MANIFEST_JSON = JSON.stringify({
  name: 'E-TRADE — Identificare produs',
  short_name: 'E-TRADE',
  start_url: '/',
  scope: '/',
  display: 'standalone',
  background_color: '#F5F6F8',
  theme_color: '#1F3A5F',
  icons: [
    { src: '/icon-192.png', sizes: '192x192', type: 'image/png', purpose: 'any maskable' },
    { src: '/icon-512.png', sizes: '512x512', type: 'image/png', purpose: 'any maskable' },
  ],
});
const SW_JS = `
self.addEventListener('install', () => self.skipWaiting());
self.addEventListener('activate', (e) => e.waitUntil(self.clients.claim()));
self.addEventListener('fetch', (event) => {
  event.respondWith(fetch(event.request).catch(() => new Response('Offline', { status: 503 })));
});
`;
const PWA_HEAD_TAGS = `
<link rel="manifest" href="/manifest.json">
<link rel="apple-touch-icon" href="/icon-192.png">
<meta name="theme-color" content="#1F3A5F">
<script>if ('serviceWorker' in navigator) { window.addEventListener('load', () => navigator.serviceWorker.register('/sw.js').catch(() => {})); }</script>
`;

// ---------- baza de date (SQLite, modul nativ Node) ----------
const db = new DatabaseSync(path.join(DATA_DIR, 'etrade.db'));
db.exec(`
  CREATE TABLE IF NOT EXISTS requests (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    created_at TEXT NOT NULL,
    companie TEXT, contact TEXT, telefon TEXT, email TEXT, urgenta TEXT,
    categorie TEXT, campuri_json TEXT, cod TEXT, descriere TEXT, foto_path TEXT,
    status TEXT NOT NULL DEFAULT 'nou',
    email_trimis INTEGER NOT NULL DEFAULT 0, email_eroare TEXT,
    webhook_trimis INTEGER NOT NULL DEFAULT 0
  );
  CREATE TABLE IF NOT EXISTS xref (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    categorie TEXT, cod_intern TEXT, eq1 TEXT, eq2 TEXT, eq3 TEXT, observatii TEXT,
    updated_at TEXT NOT NULL
  );
`);
if (db.prepare('SELECT COUNT(*) AS c FROM xref').get().c === 0) {
  const now = new Date().toISOString();
  const ins = db.prepare(`INSERT INTO xref (categorie, cod_intern, eq1, eq2, eq3, observatii, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?)`);
  ins.run('Rulmenti (exemplu)', '-', '', '', '', 'Exemplu de structura - completati cu echivalente verificate de echipa tehnica', now);
  ins.run('Garnituri (exemplu)', '-', '', '', '', 'Exemplu de structura - completati cu echivalente verificate de echipa tehnica', now);
}

// ---------- client SMTP minimal (net/tls, fara dependente) ----------
class SmtpError extends Error {}
function b64(str) { return Buffer.from(str, 'utf8').toString('base64'); }
function readResponse(socket) {
  return new Promise((resolve, reject) => {
    let buf = '';
    function onData(chunk) {
      buf += chunk.toString('utf8');
      const lines = buf.split(/\r\n/).filter(Boolean);
      const last = lines[lines.length - 1];
      if (last && /^\d{3} /.test(last)) { cleanup(); resolve({ code: parseInt(last.slice(0, 3), 10), lines, raw: buf }); }
    }
    function onError(err) { cleanup(); reject(err); }
    function onClose() { cleanup(); reject(new SmtpError('Conexiune inchisa neasteptat de server')); }
    function cleanup() { socket.removeListener('data', onData); socket.removeListener('error', onError); socket.removeListener('close', onClose); }
    socket.on('data', onData); socket.on('error', onError); socket.on('close', onClose);
  });
}
async function sendCommand(socket, command, expectedCodes) {
  if (command !== null) socket.write(command + '\r\n');
  const res = await readResponse(socket);
  if (expectedCodes && !expectedCodes.includes(res.code)) throw new SmtpError(`Raspuns SMTP neasteptat la "${command}": ${res.raw.trim()}`);
  return res;
}
async function sendMail(opts) {
  const { host, port, secure, user, pass, from, to, subject, text } = opts;
  if (!host || !port || !user || !pass || !from || !to) throw new SmtpError('Configuratie SMTP incompleta');
  let socket = secure ? tls.connect({ host, port, servername: host }) : net.connect({ host, port });
  await new Promise((resolve, reject) => { socket.once(secure ? 'secureConnect' : 'connect', resolve); socket.once('error', reject); });
  await readResponse(socket);
  await sendCommand(socket, `EHLO ${host}`, [250]);
  if (!secure) {
    await sendCommand(socket, 'STARTTLS', [220]);
    const plainSocket = socket;
    socket = tls.connect({ socket: plainSocket, host, servername: host });
    await new Promise((resolve, reject) => { socket.once('secureConnect', resolve); socket.once('error', reject); });
    await sendCommand(socket, `EHLO ${host}`, [250]);
  }
  await sendCommand(socket, 'AUTH LOGIN', [334]);
  await sendCommand(socket, b64(user), [334]);
  await sendCommand(socket, b64(pass), [235]);
  await sendCommand(socket, `MAIL FROM:<${from}>`, [250]);
  await sendCommand(socket, `RCPT TO:<${to}>`, [250, 251]);
  await sendCommand(socket, 'DATA', [354]);
  const headers = [`From: ${from}`, `To: ${to}`, `Subject: ${subject}`, `Date: ${new Date().toUTCString()}`,
    'MIME-Version: 1.0', 'Content-Type: text/plain; charset=utf-8', 'Content-Transfer-Encoding: 8bit'].join('\r\n');
  const bodyEscaped = text.replace(/\r\n/g, '\n').split('\n').map(l => (l.startsWith('.') ? '.' + l : l)).join('\r\n');
  await sendCommand(socket, `${headers}\r\n\r\n${bodyEscaped}\r\n.`, [250]);
  await sendCommand(socket, 'QUIT', [221]).catch(() => {});
  socket.end();
}

// ---------- Basic Auth pentru /admin ----------
function timingSafeEqualStr(a, b) {
  const bufA = Buffer.from(String(a)), bufB = Buffer.from(String(b));
  if (bufA.length !== bufB.length) return false;
  return crypto.timingSafeEqual(bufA, bufB);
}
function requireAdmin(req, res) {
  const user = process.env.ADMIN_USER || 'admin';
  const pass = process.env.ADMIN_PASSWORD;
  if (!pass) { res.writeHead(500, { 'Content-Type': 'application/json' }); res.end(JSON.stringify({ error: 'ADMIN_PASSWORD nu este configurat' })); return false; }
  const header = req.headers['authorization'] || '';
  const [scheme, encoded] = header.split(' ');
  if (scheme !== 'Basic' || !encoded) { res.writeHead(401, { 'WWW-Authenticate': 'Basic realm="E-TRADE admin"', 'Content-Type': 'text/plain; charset=utf-8' }); res.end('Autentificare necesara'); return false; }
  const decoded = Buffer.from(encoded, 'base64').toString('utf8');
  const sepIdx = decoded.indexOf(':');
  const gotUser = decoded.slice(0, sepIdx), gotPass = decoded.slice(sepIdx + 1);
  if (!timingSafeEqualStr(gotUser, user) || !timingSafeEqualStr(gotPass, pass)) { res.writeHead(401, { 'WWW-Authenticate': 'Basic realm="E-TRADE admin"', 'Content-Type': 'text/plain; charset=utf-8' }); res.end('Date de autentificare incorecte'); return false; }
  return true;
}

// ---------- utilitare ----------
function sendJson(res, status, obj) {
  const body = JSON.stringify(obj);
  res.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8', 'Content-Length': Buffer.byteLength(body) });
  res.end(body);
}
function sendHtml(res, html) {
  res.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8' });
  res.end(html);
}
function readJsonBody(req, maxBytes = 12 * 1024 * 1024) {
  return new Promise((resolve, reject) => {
    let size = 0; const chunks = [];
    req.on('data', (chunk) => { size += chunk.length; if (size > maxBytes) { reject(new Error('Payload prea mare')); req.destroy(); return; } chunks.push(chunk); });
    req.on('end', () => { if (chunks.length === 0) return resolve({}); try { resolve(JSON.parse(Buffer.concat(chunks).toString('utf8'))); } catch (e) { reject(new Error('JSON invalid')); } });
    req.on('error', reject);
  });
}
function saveDataUrlPhoto(id, dataUrl) {
  const match = /^data:(image\/[a-zA-Z0-9.+-]+);base64,(.+)$/.exec(dataUrl || '');
  if (!match) return null;
  const ext = (match[1].split('/')[1] || 'jpg').split('+')[0];
  const buf = Buffer.from(match[2], 'base64');
  const filePath = path.join(UPLOAD_DIR, `req-${id}.${ext}`);
  fs.writeFileSync(filePath, buf);
  return filePath;
}
function postWebhook(url, payload) {
  return new Promise((resolve) => {
    try {
      const u = new URL(url);
      const lib = u.protocol === 'http:' ? http : https;
      const body = JSON.stringify(payload);
      const req = lib.request(u, { method: 'POST', headers: { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(body) } },
        (res) => { res.resume(); resolve(res.statusCode >= 200 && res.statusCode < 300); });
      req.on('error', () => resolve(false));
      req.write(body); req.end();
    } catch (e) { resolve(false); }
  });
}
function categoryLabels() {
  return {
    mecanic: 'Piese mecanice (rulmenti, transmisii, ghidaje, cuplaje)', pneumatic: 'Componente pneumatice',
    electric: 'Electrice & senzori', lubrifianti: 'Lubrifianti & uleiuri', garnituri: 'Garnituri & etansari',
    roboti: 'Piese de schimb pentru roboti industriali', marcare: 'Marcare industriala',
    scule: 'Scule industriale & echipamente de asamblare', altele: 'Alta categorie / nu sunt sigur',
  };
}
function buildSummaryText(row) {
  const campuri = JSON.parse(row.campuri_json || '{}');
  const lines = ['CERERE IDENTIFICARE PRODUS -- E-TRADE', '', 'Nr. cerere: #' + row.id,
    'Companie: ' + (row.companie || '-'), 'Persoana contact: ' + (row.contact || '-'), 'Telefon: ' + (row.telefon || '-')];
  if (row.email) lines.push('Email: ' + row.email);
  lines.push('Urgenta: ' + (row.urgenta || 'Normal'), '', 'Categorie: ' + (categoryLabels()[row.categorie] || row.categorie));
  Object.entries(campuri).forEach(([k, v]) => { if (v) lines.push(k + ': ' + v); });
  if (row.cod) lines.push('Cod/referinta cunoscuta: ' + row.cod);
  if (row.descriere) lines.push('Descriere: ' + row.descriere);
  if (row.foto_path) lines.push('(are poza atasata in sistem)');
  return lines.join('\n');
}

// ---------- rute API ----------
async function handleCreateRequest(req, res) {
  let body;
  try { body = await readJsonBody(req); } catch (e) { return sendJson(res, 400, { error: e.message }); }
  const { companie, contact, telefon, email, urgenta, categorie, campuri, cod, descriere, fotoDataUrl } = body;
  if (!categorie) return sendJson(res, 400, { error: 'Campul "categorie" este obligatoriu.' });
  if (!telefon && !email) return sendJson(res, 400, { error: 'Este necesar cel putin un telefon sau un email de contact.' });

  const now = new Date().toISOString();
  const ins = db.prepare(`INSERT INTO requests (created_at, companie, contact, telefon, email, urgenta, categorie, campuri_json, cod, descriere, status) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'nou')`);
  const info = ins.run(now, companie || '', contact || '', telefon || '', email || '', urgenta || 'Normal', categorie, JSON.stringify(campuri || {}), cod || '', descriere || '');
  const id = Number(info.lastInsertRowid);

  let fotoPath = null;
  if (fotoDataUrl) {
    try { fotoPath = saveDataUrlPhoto(id, fotoDataUrl); } catch (e) {}
    if (fotoPath) db.prepare('UPDATE requests SET foto_path = ? WHERE id = ?').run(fotoPath, id);
  }

  const row = db.prepare('SELECT * FROM requests WHERE id = ?').get(id);
  const summaryText = buildSummaryText(row);

  let emailTrimis = false, emailEroare = null;
  console.log(`[SMTP-CHECK] cerere #${id}: HOST=${!!process.env.SMTP_HOST} USER=${!!process.env.SMTP_USER} PASS=${!!process.env.SMTP_PASS}`);
  if (process.env.SMTP_HOST && process.env.SMTP_USER && process.env.SMTP_PASS) {
    try {
      await sendMail({
        host: process.env.SMTP_HOST, port: parseInt(process.env.SMTP_PORT || '587', 10), secure: process.env.SMTP_SECURE === 'true',
        user: process.env.SMTP_USER, pass: process.env.SMTP_PASS, from: process.env.SMTP_FROM || process.env.SMTP_USER, to: NOTIFY_EMAIL,
        subject: `Cerere noua identificare produs #${id} - ${companie || 'client'}`, text: summaryText,
      });
      emailTrimis = true;
      console.log(`[SMTP-CHECK] cerere #${id}: email trimis cu succes`);
    } catch (e) {
      emailEroare = e.message || e.code || String(e) || 'eroare necunoscuta';
      console.log(`[SMTP-CHECK] cerere #${id}: EROARE la trimitere -- name=${e && e.name} code=${e && e.code} message=${e && e.message} string=${String(e)} stack=${e && e.stack}`);
    }
  }
  db.prepare('UPDATE requests SET email_trimis = ?, email_eroare = ? WHERE id = ?').run(emailTrimis ? 1 : 0, emailEroare, id);

  let webhookTrimis = false;
  if (process.env.WEBHOOK_URL) {
    webhookTrimis = await postWebhook(process.env.WEBHOOK_URL, { id, companie, contact, telefon, email, urgenta, categorie, campuri, cod, descriere, createdAt: now, summaryText });
    db.prepare('UPDATE requests SET webhook_trimis = ? WHERE id = ?').run(webhookTrimis ? 1 : 0, id);
  }

  const whatsappLink = `https://wa.me/${WHATSAPP_NUMBER}?text=${encodeURIComponent(summaryText)}`;
  sendJson(res, 201, { ok: true, id, emailTrimis, emailEroare, webhookTrimis, whatsappLink, summaryText });
}

function handleListRequests(req, res, query) {
  if (!requireAdmin(req, res)) return;
  let rows;
  if (query.q) { const like = `%${query.q}%`; rows = db.prepare(`SELECT * FROM requests WHERE companie LIKE ? OR contact LIKE ? OR cod LIKE ? OR descriere LIKE ? ORDER BY id DESC`).all(like, like, like, like); }
  else if (query.status) rows = db.prepare('SELECT * FROM requests WHERE status = ? ORDER BY id DESC').all(query.status);
  else rows = db.prepare('SELECT * FROM requests ORDER BY id DESC').all();
  rows.forEach(r => { r.campuri = JSON.parse(r.campuri_json || '{}'); delete r.campuri_json; r.are_foto = !!r.foto_path; delete r.foto_path; });
  sendJson(res, 200, rows);
}
function handleGetRequest(req, res, id) {
  if (!requireAdmin(req, res)) return;
  const row = db.prepare('SELECT * FROM requests WHERE id = ?').get(id);
  if (!row) return sendJson(res, 404, { error: 'not found' });
  row.campuri = JSON.parse(row.campuri_json || '{}'); delete row.campuri_json; row.are_foto = !!row.foto_path;
  sendJson(res, 200, row);
}
async function handleUpdateStatus(req, res, id) {
  if (!requireAdmin(req, res)) return;
  let body; try { body = await readJsonBody(req); } catch (e) { return sendJson(res, 400, { error: e.message }); }
  const allowed = ['nou', 'in lucru', 'rezolvat'];
  if (!allowed.includes(body.status)) return sendJson(res, 400, { error: 'Status invalid. Valori permise: ' + allowed.join(', ') });
  const info = db.prepare('UPDATE requests SET status = ? WHERE id = ?').run(body.status, id);
  if (info.changes === 0) return sendJson(res, 404, { error: 'not found' });
  sendJson(res, 200, { ok: true });
}
function handleGetPhoto(req, res, id) {
  if (!requireAdmin(req, res)) return;
  const row = db.prepare('SELECT foto_path FROM requests WHERE id = ?').get(id);
  if (!row || !row.foto_path || !fs.existsSync(row.foto_path)) return sendJson(res, 404, { error: 'no photo' });
  const ext = path.extname(row.foto_path).slice(1);
  fs.readFile(row.foto_path, (err, data) => { if (err) return sendJson(res, 404, { error: 'not found' }); res.writeHead(200, { 'Content-Type': `image/${ext === 'jpg' ? 'jpeg' : ext}` }); res.end(data); });
}
function handleListXref(req, res) { if (!requireAdmin(req, res)) return; sendJson(res, 200, db.prepare('SELECT * FROM xref ORDER BY id ASC').all()); }
async function handleCreateXref(req, res) {
  if (!requireAdmin(req, res)) return;
  let body; try { body = await readJsonBody(req); } catch (e) { return sendJson(res, 400, { error: e.message }); }
  const now = new Date().toISOString();
  const info = db.prepare(`INSERT INTO xref (categorie, cod_intern, eq1, eq2, eq3, observatii, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?)`)
    .run(body.categorie || '', body.cod_intern || '', body.eq1 || '', body.eq2 || '', body.eq3 || '', body.observatii || '', now);
  sendJson(res, 201, { ok: true, id: Number(info.lastInsertRowid) });
}
async function handleUpdateXref(req, res, id) {
  if (!requireAdmin(req, res)) return;
  let body; try { body = await readJsonBody(req); } catch (e) { return sendJson(res, 400, { error: e.message }); }
  const now = new Date().toISOString();
  const info = db.prepare(`UPDATE xref SET categorie=?, cod_intern=?, eq1=?, eq2=?, eq3=?, observatii=?, updated_at=? WHERE id=?`)
    .run(body.categorie || '', body.cod_intern || '', body.eq1 || '', body.eq2 || '', body.eq3 || '', body.observatii || '', now, id);
  if (info.changes === 0) return sendJson(res, 404, { error: 'not found' });
  sendJson(res, 200, { ok: true });
}
function handleDeleteXref(req, res, id) {
  if (!requireAdmin(req, res)) return;
  const info = db.prepare('DELETE FROM xref WHERE id = ?').run(id);
  if (info.changes === 0) return sendJson(res, 404, { error: 'not found' });
  sendJson(res, 200, { ok: true });
}

// ---------- server HTTP + rutare ----------
const server = http.createServer(async (req, res) => {
  const parsed = new URL(req.url, `http://${req.headers.host}`);
  const pathname = parsed.pathname;
  const query = Object.fromEntries(parsed.searchParams.entries());
  try {
    if (req.method === 'GET' && pathname === '/health') return sendJson(res, 200, { ok: true, time: new Date().toISOString() });
    if (req.method === 'GET' && pathname === '/') return sendHtml(res, INDEX_HTML.replace('</head>', PWA_HEAD_TAGS + '</head>'));
    if (req.method === 'GET' && pathname === '/admin') { if (!requireAdmin(req, res)) return; return sendHtml(res, ADMIN_HTML.replace('</head>', PWA_HEAD_TAGS + '</head>')); }
    if (req.method === 'GET' && pathname === '/manifest.json') { res.writeHead(200, { 'Content-Type': 'application/manifest+json' }); return res.end(MANIFEST_JSON); }
    if (req.method === 'GET' && pathname === '/sw.js') { res.writeHead(200, { 'Content-Type': 'application/javascript' }); return res.end(SW_JS); }
    if (req.method === 'GET' && pathname === '/icon-192.png') { res.writeHead(200, { 'Content-Type': 'image/png' }); return res.end(ICON_192); }
    if (req.method === 'GET' && pathname === '/icon-512.png') { res.writeHead(200, { 'Content-Type': 'image/png' }); return res.end(ICON_512); }
    if (req.method === 'POST' && pathname === '/api/requests') return await handleCreateRequest(req, res);
    if (req.method === 'GET' && pathname === '/api/admin/requests') return handleListRequests(req, res, query);
    let m;
    if (req.method === 'GET' && (m = pathname.match(/^\/api\/admin\/requests\/(\d+)$/))) return handleGetRequest(req, res, Number(m[1]));
    if (req.method === 'PATCH' && (m = pathname.match(/^\/api\/admin\/requests\/(\d+)$/))) return await handleUpdateStatus(req, res, Number(m[1]));
    if (req.method === 'GET' && (m = pathname.match(/^\/api\/admin\/requests\/(\d+)\/foto$/))) return handleGetPhoto(req, res, Number(m[1]));
    if (req.method === 'GET' && pathname === '/api/admin/xref') return handleListXref(req, res);
    if (req.method === 'POST' && pathname === '/api/admin/xref') return await handleCreateXref(req, res);
    if (req.method === 'PUT' && (m = pathname.match(/^\/api\/admin\/xref\/(\d+)$/))) return await handleUpdateXref(req, res, Number(m[1]));
    if (req.method === 'DELETE' && (m = pathname.match(/^\/api\/admin\/xref\/(\d+)$/))) return handleDeleteXref(req, res, Number(m[1]));
    sendJson(res, 404, { error: 'not found' });
  } catch (err) { console.error(err); sendJson(res, 500, { error: 'Eroare interna: ' + err.message }); }
});

server.listen(PORT, () => {
  console.log(`E-TRADE identificare produse - server pornit pe portul ${PORT}`);
  if (!process.env.ADMIN_PASSWORD) console.log('  ATENTIE: ADMIN_PASSWORD nu e setat -> panoul admin va raspunde cu eroare pana il configurati.');
  if (!process.env.SMTP_HOST || !process.env.SMTP_USER || !process.env.SMTP_PASS) {
    const lipsa = ['SMTP_HOST', 'SMTP_USER', 'SMTP_PASS'].filter(k => !process.env[k]);
    console.log('  Info: SMTP neconfigurat (lipsesc: ' + lipsa.join(', ') + ') -> emailurile automate sunt dezactivate (cererile tot se salveaza).');
  } else {
    console.log('  Info: SMTP configurat (host=' + process.env.SMTP_HOST + ', user=' + process.env.SMTP_USER + ').');
  }
});

module.exports = server;
